package br.edu.scoa.academico.infraestrutura.persistencia;

import br.edu.scoa.academico.aplicacao.turmas.*;
import br.edu.scoa.academico.dominio.turmas.*;
import java.sql.*; import java.time.*; import java.util.*;
import static br.edu.scoa.academico.dominio.turmas.FalhaTurma.Codigo.*;

public final class RepositorioTurmasMysql implements RepositorioTurmas {
 private final ConfiguracaoBanco banco; public RepositorioTurmasMysql(ConfiguracaoBanco banco){this.banco=banco;}
 public Sala salvarSala(Sala sala,UUID op,long autor,Instant instante){ if(op==null)throw new FalhaTurma(OPERACAO_REUTILIZADA); try(var c=banco.abrir()){
  c.setAutoCommit(false);try{long id=sala.id(),v=sala.revisao()+1;if(id==0){try(var s=c.prepareStatement("INSERT INTO sala(identificacao,localizacao,capacidade,recursos,situacao,versao_registro,operacao_criacao) VALUES(?,?,?,?,?,1,?)",Statement.RETURN_GENERATED_KEYS)){s.setString(1,sala.identificacao());s.setString(2,sala.localizacao());s.setInt(3,sala.capacidade());s.setString(4,sala.recursos());s.setString(5,sala.situacao().name());s.setString(6,op.toString());s.executeUpdate();try(var r=s.getGeneratedKeys()){r.next();id=r.getLong(1);}}}else{try(var s=c.prepareStatement("UPDATE sala SET identificacao=?,localizacao=?,capacidade=?,recursos=?,situacao=?,versao_registro=? WHERE id=? AND versao_registro=?")){s.setString(1,sala.identificacao());s.setString(2,sala.localizacao());s.setInt(3,sala.capacidade());s.setString(4,sala.recursos());s.setString(5,sala.situacao().name());s.setLong(6,v);s.setLong(7,id);s.setLong(8,sala.revisao());if(s.executeUpdate()!=1)throw new FalhaTurma(CONFLITO_EDICAO);}}
  try(var sa=c.prepareStatement("INSERT INTO sala_auditoria(sala_id,evento,autor_id,instante,operacao_id) VALUES(?,?,?,?,?)")){sa.setLong(1,id);sa.setString(2,sala.id()==0?"CADASTRO":"EDICAO");sa.setLong(3,autor);sa.setTimestamp(4,Timestamp.from(instante));sa.setString(5,op.toString());sa.executeUpdate();}
  c.commit();return sala.identificado(id,v);}catch(Exception e){c.rollback();if(e instanceof FalhaTurma f)throw f;if(e instanceof SQLException x&&x.getErrorCode()==1062){if(x.getMessage()!=null&&(x.getMessage().contains("operacao")||x.getMessage().contains("uk_sala_auditoria_operacao")||x.getMessage().contains("uk_sala_operacao")))throw new FalhaTurma(OPERACAO_REUTILIZADA);throw new FalhaTurma(SALA_INVALIDA);}throw new FalhaTurma(INDISPONIVEL);}}catch(SQLException e){throw new FalhaTurma(INDISPONIVEL);}}
 public Optional<Sala> consultarSala(long id){try(var c=banco.abrir();var s=c.prepareStatement("SELECT * FROM sala WHERE id=?")){s.setLong(1,id);try(var r=s.executeQuery()){return r.next()?Optional.of(lerSala(r)):Optional.empty();}}catch(SQLException e){throw new FalhaTurma(INDISPONIVEL);}}
 public List<Sala> pesquisarSalas(String t){var itens=new ArrayList<Sala>();try(var c=banco.abrir();var s=c.prepareStatement("SELECT * FROM sala WHERE LOCATE(?,identificacao)>0 OR LOCATE(?,localizacao)>0 ORDER BY identificacao")){s.setString(1,t);s.setString(2,t);try(var r=s.executeQuery()){while(r.next())itens.add(lerSala(r));}return List.copyOf(itens);}catch(SQLException e){throw new FalhaTurma(INDISPONIVEL);}}
 public Turma salvarTurma(Turma turma,UUID op,long autor,Instant instante){if(op==null)throw new FalhaTurma(OPERACAO_REUTILIZADA);try(var c=banco.abrir()){c.setAutoCommit(false);try{verificarConflitos(c,turma);long id=turma.id(),v=turma.revisao()+1;if(id!=0)throw new FalhaTurma(CONFLITO_EDICAO);try(var s=c.prepareStatement("INSERT INTO turma(periodo_id,disciplina_id,professor_id,codigo,capacidade,situacao,versao_registro,operacao_criacao) VALUES(?,?,?,?,?,?,1,?)",Statement.RETURN_GENERATED_KEYS)){s.setLong(1,turma.periodoId());s.setLong(2,turma.disciplinaId());s.setLong(3,turma.professorId());s.setString(4,turma.codigo());s.setInt(5,turma.capacidade());s.setString(6,turma.situacao().name());s.setString(7,op.toString());s.executeUpdate();try(var r=s.getGeneratedKeys()){r.next();id=r.getLong(1);}}var horarios=new ArrayList<HorarioTurma>();for(var h:turma.horarios())horarios.add(inserirHorario(c,id,h));try(var s=c.prepareStatement("INSERT INTO turma_auditoria(turma_id,evento,autor_id,instante,operacao_id) VALUES(?,'CADASTRO',?,?,?)")){s.setLong(1,id);s.setLong(2,autor);s.setTimestamp(3,Timestamp.from(instante));s.setString(4,op.toString());s.executeUpdate();}c.commit();return turma.identificado(id,v,horarios);}catch(Exception e){c.rollback();if(e instanceof FalhaTurma f)throw f;if(e instanceof SQLException x&&x.getErrorCode()==1062)throw new FalhaTurma(TURMA_INVALIDA);throw new FalhaTurma(INDISPONIVEL);}}catch(SQLException e){throw new FalhaTurma(INDISPONIVEL);}}
 private void verificarConflitos(Connection c,Turma t)throws SQLException{for(var h:t.horarios()){try(var s=c.prepareStatement("SELECT h.id FROM horario_turma h JOIN turma x ON x.id=h.turma_id WHERE x.periodo_id=? AND x.professor_id=? AND h.dia_semana=? AND ? < h.hora_fim AND h.hora_inicio < ? FOR UPDATE")){s.setLong(1,t.periodoId());s.setLong(2,t.professorId());s.setString(3,h.diaSemana().name());s.setObject(4,h.horaInicio());s.setObject(5,h.horaFim());try(var r=s.executeQuery()){if(r.next())throw new FalhaTurma(CONFLITO_PROFESSOR);}}if(h.salaId()!=null)try(var s=c.prepareStatement("SELECT h.id FROM horario_turma h JOIN turma x ON x.id=h.turma_id WHERE x.periodo_id=? AND h.sala_id=? AND h.dia_semana=? AND ? < h.hora_fim AND h.hora_inicio < ? FOR UPDATE")){s.setLong(1,t.periodoId());s.setLong(2,h.salaId());s.setString(3,h.diaSemana().name());s.setObject(4,h.horaInicio());s.setObject(5,h.horaFim());try(var r=s.executeQuery()){if(r.next())throw new FalhaTurma(CONFLITO_SALA);}}}}
 private HorarioTurma inserirHorario(Connection c,long turmaId,HorarioTurma h)throws SQLException{try(var s=c.prepareStatement("INSERT INTO horario_turma(turma_id,sala_id,dia_semana,hora_inicio,hora_fim,versao_registro) VALUES(?,?,?,?,?,1)",Statement.RETURN_GENERATED_KEYS)){s.setLong(1,turmaId);if(h.salaId()==null)s.setNull(2,Types.BIGINT);else s.setLong(2,h.salaId());s.setString(3,h.diaSemana().name());s.setObject(4,h.horaInicio());s.setObject(5,h.horaFim());s.executeUpdate();try(var r=s.getGeneratedKeys()){r.next();return h.identificado(r.getLong(1),1);}}}
 public Optional<Turma> consultarTurma(long id){try(var c=banco.abrir()){return lerTurma(c,id);}catch(SQLException e){throw new FalhaTurma(INDISPONIVEL);}}
 public Turma transicionarTurma(long id,long revisao,SituacaoTurma destino,UUID op,long autor,Instant instante){
  if(op==null)throw new FalhaTurma(OPERACAO_REUTILIZADA);try(var c=banco.abrir()){c.setAutoCommit(false);try{var atual=lerTurma(c,id).orElseThrow(()->new FalhaTurma(NAO_ENCONTRADO));if(atual.revisao()!=revisao)throw new FalhaTurma(CONFLITO_EDICAO);
   try(var s=c.prepareStatement("UPDATE turma SET situacao=?,versao_registro=versao_registro+1 WHERE id=? AND versao_registro=?")){s.setString(1,destino.name());s.setLong(2,id);s.setLong(3,revisao);if(s.executeUpdate()!=1)throw new FalhaTurma(CONFLITO_EDICAO);}
   auditar(c,id,"TRANSICAO_"+destino,op,autor,instante);c.commit();return new Turma(id,atual.periodoId(),atual.disciplinaId(),atual.professorId(),atual.codigo(),atual.capacidade(),destino,atual.horarios(),revisao+1);
  }catch(Exception e){c.rollback();if(e instanceof FalhaTurma f)throw f;throw new FalhaTurma(INDISPONIVEL);}}catch(SQLException e){throw new FalhaTurma(INDISPONIVEL);}}
 public Turma alocarSala(long turmaId,long horarioId,long revisaoTurma,long revisaoHorario,Long salaId,UUID op,long autor,Instant instante){
  if(op==null)throw new FalhaTurma(OPERACAO_REUTILIZADA);try(var c=banco.abrir()){c.setAutoCommit(false);try{var turma=lerTurma(c,turmaId).orElseThrow(()->new FalhaTurma(NAO_ENCONTRADO));if(turma.revisao()!=revisaoTurma)throw new FalhaTurma(CONFLITO_EDICAO);var horario=turma.horarios().stream().filter(h->h.id()==horarioId).findFirst().orElseThrow(()->new FalhaTurma(NAO_ENCONTRADO));if(horario.revisao()!=revisaoHorario)throw new FalhaTurma(CONFLITO_EDICAO);
   if(salaId!=null){try(var sala=c.prepareStatement("SELECT capacidade,situacao FROM sala WHERE id=? FOR UPDATE")){sala.setLong(1,salaId);try(var r=sala.executeQuery()){if(!r.next())throw new FalhaTurma(NAO_ENCONTRADO);if(!"DISPONIVEL".equals(r.getString("situacao")))throw new FalhaTurma(SALA_INDISPONIVEL);if(r.getInt("capacidade")<turma.capacidade())throw new FalhaTurma(CAPACIDADE_INSUFICIENTE);}}try(var conflito=c.prepareStatement("SELECT h.id FROM horario_turma h JOIN turma t ON t.id=h.turma_id WHERE t.periodo_id=? AND h.sala_id=? AND h.dia_semana=? AND ? < h.hora_fim AND h.hora_inicio < ? AND h.id<>? FOR UPDATE")){conflito.setLong(1,turma.periodoId());conflito.setLong(2,salaId);conflito.setString(3,horario.diaSemana().name());conflito.setObject(4,horario.horaInicio());conflito.setObject(5,horario.horaFim());conflito.setLong(6,horarioId);try(var r=conflito.executeQuery()){if(r.next())throw new FalhaTurma(CONFLITO_SALA);}}}
   try(var s=c.prepareStatement("UPDATE horario_turma SET sala_id=?,versao_registro=versao_registro+1 WHERE id=? AND versao_registro=?")){if(salaId==null)s.setNull(1,Types.BIGINT);else s.setLong(1,salaId);s.setLong(2,horarioId);s.setLong(3,revisaoHorario);if(s.executeUpdate()!=1)throw new FalhaTurma(CONFLITO_EDICAO);}try(var s=c.prepareStatement("UPDATE turma SET versao_registro=versao_registro+1 WHERE id=? AND versao_registro=?")){s.setLong(1,turmaId);s.setLong(2,revisaoTurma);if(s.executeUpdate()!=1)throw new FalhaTurma(CONFLITO_EDICAO);}auditar(c,turmaId,salaId==null?"DESALOCACAO":"ALOCACAO",op,autor,instante);c.commit();return lerTurma(c,turmaId).orElseThrow(()->new FalhaTurma(NAO_ENCONTRADO));
  }catch(Exception e){c.rollback();if(e instanceof FalhaTurma f)throw f;throw new FalhaTurma(INDISPONIVEL);}}catch(SQLException e){throw new FalhaTurma(INDISPONIVEL);}}
 public List<Turma> pesquisarTurmas(long periodoId){var itens=new ArrayList<Turma>();try(var c=banco.abrir();var s=c.prepareStatement("SELECT id FROM turma WHERE periodo_id=? ORDER BY codigo")){s.setLong(1,periodoId);try(var r=s.executeQuery()){while(r.next())lerTurma(c,r.getLong(1)).ifPresent(itens::add);}return List.copyOf(itens);}catch(SQLException e){throw new FalhaTurma(INDISPONIVEL);}}
 public List<Turma> todas(){return buscarTurmas("SELECT id FROM turma ORDER BY periodo_id DESC,codigo",0);}
 public List<Turma> porProfessor(long professorId){if(professorId<=0)throw new FalhaTurma(TURMA_INVALIDA);return buscarTurmas("SELECT id FROM turma WHERE professor_id=? ORDER BY periodo_id DESC,codigo",professorId);}
 private List<Turma> buscarTurmas(String sql,long parametro){var itens=new ArrayList<Turma>();try(var c=banco.abrir();var s=c.prepareStatement(sql)){if(parametro>0)s.setLong(1,parametro);try(var r=s.executeQuery()){while(r.next())lerTurma(c,r.getLong(1)).ifPresent(itens::add);}return List.copyOf(itens);}catch(SQLException e){throw new FalhaTurma(INDISPONIVEL);}}
 private Optional<Turma> lerTurma(Connection c,long id)throws SQLException{try(var s=c.prepareStatement("SELECT * FROM turma WHERE id=?")){s.setLong(1,id);try(var r=s.executeQuery()){if(!r.next())return Optional.empty();var hs=new ArrayList<HorarioTurma>();try(var h=c.prepareStatement("SELECT * FROM horario_turma WHERE turma_id=? ORDER BY dia_semana,hora_inicio")){h.setLong(1,id);try(var rh=h.executeQuery()){while(rh.next())hs.add(new HorarioTurma(rh.getLong("id"),DiaSemana.valueOf(rh.getString("dia_semana")),rh.getObject("hora_inicio",LocalTime.class),rh.getObject("hora_fim",LocalTime.class),(Long)rh.getObject("sala_id"),rh.getLong("versao_registro")));}}return Optional.of(new Turma(id,r.getLong("periodo_id"),r.getLong("disciplina_id"),r.getLong("professor_id"),r.getString("codigo"),r.getInt("capacidade"),SituacaoTurma.valueOf(r.getString("situacao")),hs,r.getLong("versao_registro")));}}}
 private Sala lerSala(ResultSet r)throws SQLException{return new Sala(r.getLong("id"),r.getString("identificacao"),r.getString("localizacao"),r.getInt("capacidade"),r.getString("recursos"),SituacaoSala.valueOf(r.getString("situacao")),r.getLong("versao_registro"));}
 private void auditar(Connection c,long turmaId,String evento,UUID op,long autor,Instant instante)throws SQLException{try(var s=c.prepareStatement("INSERT INTO turma_auditoria(turma_id,evento,autor_id,instante,operacao_id) VALUES(?,?,?,?,?)")){s.setLong(1,turmaId);s.setString(2,evento);s.setLong(3,autor);s.setTimestamp(4,Timestamp.from(instante));s.setString(5,op.toString());s.executeUpdate();}}
}
